package com.wayrapass.controller; import com.wayrapass.dto.request.CatalogRequests;import com.wayrapass.dto.response.CatalogResponses;import com.wayrapass.service.CatalogService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/routes") @RequiredArgsConstructor public class RouteController{private final CatalogService s;@GetMapping public List<CatalogResponses.Route> all(){return s.routes();}@GetMapping("/{id}") public CatalogResponses.Route one(@PathVariable Long id){return s.route(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasRole('COORDINATOR')") public CatalogResponses.Route create(@Valid @RequestBody CatalogRequests.Route r){return s.saveRoute(null,r);}@PutMapping("/{id}") @PreAuthorize("hasRole('COORDINATOR')") public CatalogResponses.Route update(@PathVariable Long id,@Valid @RequestBody CatalogRequests.Route r){return s.saveRoute(id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @PreAuthorize("hasRole('COORDINATOR')") public void delete(@PathVariable Long id){s.deleteRoute(id);}}
